from oct11_seo_bodies._html import assemble, related


def body() -> str:
    return assemble(
        intro="The <strong>Specific Carbohydrate Diet (SCD)</strong> removes many grains, certain sugars, and most processed foods. People with Crohn's disease or ulcerative colitis compare SCD with Mediterranean eating and research diets such as DINE CD. This page explains rules, nutrient gaps, evidence limits, and supervision needs. Education only.",
        sections=[('SCD rules in patient language', ['SCD allows specific fruits, vegetables, meats, nuts, and fermented dairy while excluding conventional starches and disaccharides per community legal lists.', 'Home cooking dominates because restaurant thickeners and starches are hard to verify.', 'Legal lists update slowly; bring questions to dietitians rather than forum arguments.', 'Children need calorie density monitoring when entire food groups disappear.']), ('Evidence and realistic expectations', ['Small studies and surveys report symptom relief in selected IBD patients, yet trial quality varies compared with Mediterranean interventions in adults.', 'SCD is not proven to replace medicines for everyone.', 'Endoscopy healing should guide major treatment decisions, not stool frequency alone.', 'Maintain follow up scopes or calprotectin checks your GI recommends.']), ('SCD compared with Mediterranean patterns', ['Mediterranean eating usually keeps oats, legumes, and whole grains central with olive oil and fish.', 'SCD removes staples many Mediterranean recipes require, affecting social meals and grocery cost.', 'Some families blend ideas after structured trials end, under professional eyes.', 'Flavor and culture matter for long adherence; rigid shame cycles backfire.']), ('DINE CD themes in plain words', ["DINE CD studied Mediterranean style eating with optional modules in Crohn's disease, reporting inflammatory marker improvements in some participants versus usual education.", 'DINE CD is not identical to SCD; less extreme restriction is a common adult takeaway.', 'Ask whether local centers offer DINE style counseling.', 'Compare goals: induction support versus lifelong flexibility.']), ('Nutrient gaps to monitor', ['Calcium, vitamin D, thiamine, folate, and fiber may fall low without planning.', 'Bone health labs deserve attention when dairy is limited.', 'Pregnant patients need explicit calorie and folate planning.', 'Periodic dietitian review beats guessing from multivitamin marketing.']), ('Mental health and social load', ['Strict lists increase restaurant anxiety and family tension.', 'Pair trials with stop dates and counseling when restriction becomes identity.', 'Teens may hide disordered patterns behind SCD virtue language; watch for secrecy.', 'Support groups focused on adherence without flexibility can harm; choose balanced communities.']), ('Structured trial method', ['Baseline labs and weight, two to four week structured trial, symptom logs, and scheduled exit or reintroduction prevent endless restriction.', 'Change one variable at a time when testing tolerance.', 'Do not stack secret supplement stacks suggested online.', 'Write stop rules if weight drops or mood crashes.']), ('SCD during flares versus remission', ['Severe flares may need medical nutrition therapy or gentle textures before restrictive patterns.', 'Starting SCD mid flare can blur whether medicines or diet moved markers.', 'Remission trials offer cleaner attribution with your team.', 'Hospitalized patients should follow inpatient guidance first.']), ('Ulcerative colitis readers', ["Some UC patients attempt SCD, yet evidence is thinner than in Crohn's disease.", 'Rectal bleeding and iron still need medical attention regardless of diet purity.', 'Do not delay scope surveillance because symptoms feel diet controlled.', "Supervision remains essential for UC as for Crohn's."]), ('Kitchen workflow tips', ['Batch cook legal proteins and freeze portions for fatigue days.', 'Keep separate cutting boards if household members eat starches you avoid.', 'Travel with safe snacks because airports rarely cater to SCD.', 'Instant pot yogurt steps appear in community books; confirm pasteurization safety with dietitians.']), ('When SCD is a poor fit', ['Complex strictures, short bowel, eating disorder history, or uncontrolled malnutrition need different pathways.', 'If SCD social media increases shame, pause and discuss with behavioral health.', 'Insurance may not cover extra dietitian visits; still prioritize safety over trend.', 'Switching from SCD to inclusive remission eating also deserves professional planning.']), ('Talking with your GI and dietitian', ['Bring legal lists you follow, typical day of eating, weight trend, and recent labs.', 'Ask how SCD interacts with current biologics or steroids.', 'Request written reintroduction priorities instead of vague someday guidance.', 'Second opinions from IBD dietitians help when local access is thin.']), ('SCD and microbiome hype', ['Online posts link SCD to microbiome shifts; science is evolving and individual.', 'Stool tests marketed to consumers rarely guide personal SCD legality lists.', 'Treat microbiome claims as conversation starters with researchers, not orders.', 'Focus on symptoms, weight, and inflammation markers you can track clinically.']), ('Exit ramps and reintroduction', ['Plan category reintroduction even if SCD helped; long term micronutrient diversity matters.', 'Celebrate foods that return without symptoms instead of fearing entire aisles forever.', 'If reintroduction fails, log details before blaming the wrong ingredient.', 'Some patients maintain a hybrid plate: SCD breakfast, Mediterranean dinner, with team approval.']), ('SCD legal list navigation tips', ['Print the current legal illegal list from sources your dietitian trusts, not random PDF reposts.', 'Highlight proteins and fats you already enjoy to avoid buying twelve unfamiliar flours at once.', 'Cross check yogurt fermentation steps with food safety guides for immunocompromised patients.', 'Honey as sweetener still counts toward portion awareness for diarrhea predominant patterns.']), ('Budget and time reality checks', ['Almond flour and specialty ingredients raise grocery bills; plan staples before committing monthly.', 'Batch cooking legal stews freezes well for fatigue days during trials.', 'Compare cost of SCD specialty products versus dietitian led Mediterranean meal kits if available.', 'Food assistance programs may not cover niche items; ask social work about alternatives.']), ('SCD and microbiome test marketing', ['Direct to consumer microbiome kits rarely tell you which legal foods to add tomorrow.', 'Treat microbiome claims as research evolving rather than shopping lists.', 'Stool testing for inflammation belongs in clinic labs, not wellness app upsells.', 'Focus on weight, symptoms, and calprotectin you can discuss with GI.']), ('Combining SCD with family meals', ['Serve SCD legal protein and veg while family adds rice or pasta on separate plates.', 'Date nights may need home cooked legal meals before attempting restaurants.', 'Potluck events benefit from bringing your own labeled dish without apologizing.', 'Holiday traditions can keep flavors via legal herbs while skipping forbidden sides.']), ('SCD medication and absorption', ['Malabsorption may affect how some medicines absorb during severe inflammation regardless of diet purity.', 'Do not change drug doses because SCD forums suggest it.', 'Report new nausea or pill vomiting to pharmacists and GI promptly.', 'Timed release tablets should not be crushed without pharmacist approval.']), ('Growth and pediatric SCD oversight', ['Pediatric dietitians plot growth curves monthly during SCD trials.', 'School lunches need legal packed options kids will actually eat.', 'Psychology support helps teens who feel isolated at pizza days.', 'Athletes need calorie dense legal snacks so performance does not crash.']), ('SCD exit conversations', ['Plan reintroduction categories before you start so exit feels intentional.', 'Some legal foods become lifelong friends while others were never worth cost.', 'Hybrid eating plans may emerge; document what stuck in IBDPal.', 'If SCD failed clinically, debrief without self blame to choose next tool.']), ('Travel while on SCD', ['Pack legal snacks, ice packs, and translation cards explaining dietary needs abroad.', 'Airplane meals rarely comply; pre eat legal proteins before long flights.', 'Research grocery chains at destination for legal produce and meats.', 'Travel diarrhea still requires infection workup even if diet was perfect.']), ('Batch legal snacks for desk workers', ['Hard boil eggs, portion legal cheeses, and slice cucumbers for grab containers Sunday night.', 'Keep legal fruit in visible bowls so hunger does not drive vending machine starches.', 'Desk lunches in insulated bags reduce temptation to order forbidden noodles.', 'Microwave legal stews in glass containers instead of plastic when possible.']), ('SCD and holiday tables', ['Bring legal dessert alternatives so you still feel included at celebrations.', 'Teach hosts one sentence: medical diet, not preference, no need for special commentary at table.', 'Focus conversation on people not your plate to reduce spotlight anxiety.', 'Post holiday symptom logs clarify whether travel or food drove any shifts.']), ('Reading scientific abstracts carefully', ['Abstracts mention sample sizes; tiny studies may not fit your adult extensive colitis case.', 'Ask librarians or clinicians to obtain full papers when forums cite titles incorrectly.', 'Notice funding sources in nutrition studies without cynicism but with context.', 'Evidence quality beats anecdote volume in group chats.']), ('When friends ask why you eat weird', ['Short answer: doctor supervised trial for my gut disease, thanks for understanding.', 'Long answer belongs to trusted friends only, not cafeteria audiences.', 'Humor can deflect; never owe graphic symptoms to curious coworkers.', 'Offer to share IBDPal education links if someone genuinely wants to learn.']), ('SCD pantry organization', ['Separate legal shelves at eye level; forbidden family foods on lower shelves for kids.', 'Clear containers show legal snacks at a glance during brain fog flares.', 'Inventory spreadsheet prevents buying duplicate almond flour bags.', 'Donate unopened forbidden foods after trials end if household agrees.']), ('Follow up labs after SCD trials', ['Repeat vitamin D and iron after three months on restrictive patterns.', 'Weight checks monthly on home scale same time of day.', 'Calprotectin or scope schedules continue independent of diet enthusiasm.', 'Bring lab printouts to dietitian even when numbers look fine to you.']), ('SCD journaling prompts', ['Write daily legal meals, stool count, mood score, and energy zero to ten during trials.', 'Note social events that complicated adherence without judging yourself.', 'Circle foods you miss most to prioritize reintroduction conversations.', 'Bring journal highlights to dietitian rather than raw unstructured diary only.']), ('SCD friendly travel snacks', ['Legal jerky, bananas, and hard boiled eggs travel better than airport pretzels.', 'Cooler bags extend road trip options when hotels lack fridges.', 'Research grocery delivery to hotel at destination city.', 'Keep receipts if medical expense accounts apply in your tax situation per accountant advice.']), ('Handling accidental forbidden bites', ['One mistake is data, not moral failure; log symptoms and tell dietitian honestly.', 'Do not purge or starve as punishment; follow medical guidance.', 'Children need calm adult reactions to accidental school cupcake exposures.', 'Adjust next meals gently back to legal lists without dramatic fasts.']), ('SCD and bone density', ['Restrictive diets may affect calcium intake; DEXA schedules follow risk factors.', 'Weight bearing exercise supports bones when joints allow.', 'Vitamin D supplements depend on labs, not guesswork.', 'Steroid history plus SCD restriction doubles reason for bone monitoring.']), ('Closing planning notes for your next clinic visit', ['Print or bookmark the sections that matched your week, cross out what did not, and bring one page of questions instead of relying on memory in a rushed appointment.', 'Ask for written flare and remission targets so home experiments stay aligned with scope results, calprotectin trends, and the medicine plan you already follow.', 'If a paragraph felt confusing, note the heading in your portal message so clinicians know exactly where you need clearer guidance rather than a vague request for help.', 'Small steady steps beat dramatic overhauls that collapse after three days; consistency of logging and follow up usually matters more than perfect adherence to internet lists.'])],
        clinic_quote='I am comparing SCD with Mediterranean or DINE CD style eating for my IBD. Which pattern fits my phenotype, and how will we monitor labs and weight if I try a restrictive trial?',
        faqs=[('Is SCD safe during a flare?', 'Flares may need medical nutrition first. Ask whether gentle textures should precede restrictive trials.'), ('Can SCD cure IBD?', 'No diet reliably cures IBD. Diets may support symptoms alongside prescribed treatments.'), ('Is almond flour mandatory?', 'Community recipes use almond flour often; nutrient balance still needs review.'), ('Does SCD conflict with CDED?', 'They differ; running both without guidance creates conflicting rules.')],
        related_html=related(
            ("Mediterranean diet", "/blog/mediterranean-diet-autoimmune"),
            ("CDED overview", "/blog/cded-crohns-exclusion-diet-ibd"),
            ("FODMAP overview", "/blog/fodmap-diet-crohns-colitis"),
            ("Flare foods", "/blog/flare-foods-ibd"),
        ),
        closing=['Restrictive trials deserve exit plans. Nutrition quality over the decade matters as much as the first enthusiastic month.'],
    )
